+    // Vaults (and vaults being opened) that want firewalld's panic mode on
+    QSet<QString> devicesRequestingFirewallPanicMode;
+    // Whether we have already tried to turn the panic mode on for the vaults that are open,
+    // so that the user is not asked to authenticate again if they refused
+    bool isFirewallPanicModeRequested = false;
+    // Whether we have turned the panic mode on, so we never turn off
+    // a panic mode that the user enabled by themselves
+    bool isFirewallPanicModeEnabled = false;
+    bool isFirewallPanicModeChanging = false;
+
+    void updateFirewallPanicMode(QObject *context)
+    {
+        if (isFirewallPanicModeChanging) {
+            return;
+        }
+
+        const bool shouldBeEnabled = !devicesRequestingFirewallPanicMode.isEmpty();
+
+        if (shouldBeEnabled) {
+            if (isFirewallPanicModeRequested) {
+                return;
+            }
+            isFirewallPanicModeRequested = true;
+
+        } else {
+            isFirewallPanicModeRequested = false;
+            if (!isFirewallPanicModeEnabled) {
+                return;
+            }
+        }
+
+        auto message = QDBusMessage::createMethodCall(QStringLiteral("org.fedoraproject.FirewallD1"),
+                                                      QStringLiteral("/org/fedoraproject/FirewallD1"),
+                                                      QStringLiteral("org.fedoraproject.FirewallD1"),
+                                                      shouldBeEnabled ? QStringLiteral("enablePanicMode") : QStringLiteral("disablePanicMode"));
+        message.setInteractiveAuthorizationAllowed(true);
+
+        isFirewallPanicModeChanging = true;
+
+        // No timeout, the user might need to authenticate first
+        auto watcher = new QDBusPendingCallWatcher(QDBusConnection::systemBus().asyncCall(message, std::numeric_limits<int>::max()), context);
+
+        QObject::connect(watcher, &QDBusPendingCallWatcher::finished, context, [this, context, shouldBeEnabled](QDBusPendingCallWatcher *watcher) {
+            watcher->deleteLater();
+            isFirewallPanicModeChanging = false;
+
+            const QDBusPendingReply<> reply = *watcher;
+            if (reply.isError()) {
+                // When enabling, either the panic mode was already on, or the user did not allow it
+                qWarning() << "Failed to change the firewall panic mode:" << reply.error().message();
+                if (!shouldBeEnabled) {
+                    isFirewallPanicModeEnabled = false;
+                }
+
+            } else {
+                isFirewallPanicModeEnabled = shouldBeEnabled;
+
+                auto config = KSharedConfig::openStateConfig(PLASMAVAULT_CONFIG_FILE);
+                KConfigGroup configGroup(config, "NetworkingConfig");
+                if (isFirewallPanicModeEnabled) {
+                    configGroup.writeEntry("is-firewall-panic-mode-enabled", true);
+                } else {
+                    configGroup.deleteEntry("is-firewall-panic-mode-enabled");
+                }
+                configGroup.sync();
+            }
+
+            // Vaults might have been opened or closed in the meantime
+            updateFirewallPanicMode(context);
+        });
+    }
+
     Vault *vaultFor(const QString &device_) const
     {
         const Device device(device_);
@@ -164,6 +240,19 @@ PlasmaVaultService::PlasmaVaultService(QObject *parent, const QVariantList &)
             configGroup.deleteEntry("is-networking-inhibited");
