     }
+
+    // Turn off the firewall panic mode that we left on, unless its vault is still open
+    for (const auto *vault : d->knownVaults.values()) {
+        if (vault->status() == VaultInfo::Opened && vault->usesFirewallPanicMode()) {
+            d->devicesRequestingFirewallPanicMode << vault->device().data();
+        }
+    }
+
+    auto config = KSharedConfig::openStateConfig(PLASMAVAULT_CONFIG_FILE);
+    KConfigGroup configGroup(config, "NetworkingConfig");
+    d->isFirewallPanicModeEnabled = configGroup.readEntry("is-firewall-panic-mode-enabled", false);
+    d->isFirewallPanicModeRequested = d->isFirewallPanicModeEnabled;
+    d->updateFirewallPanicMode(this);
 }

 PlasmaVaultService::~PlasmaVaultService()
@@ -296,6 +385,13 @@ void PlasmaVaultService::onVaultStatusChanged(VaultInfo::Status status)
         d->restoreNetworkingState();
     }

+    if (status == VaultInfo::Opened && vault->usesFirewallPanicMode()) {
+        d->devicesRequestingFirewallPanicMode << vault->device().data();
+    } else if (status != VaultInfo::Opened) {
+        d->devicesRequestingFirewallPanicMode.remove(vault->device().data());
+    }
+    d->updateFirewallPanicMode(this);
+
     Q_EMIT vaultChanged(vault->info());
 }

